import sys; sys.path.insert(0,str(WORK))
from lib import *
F = np.load(WORK/'base_feats.npz'); y=F['y']
M = {L: F[f'mean_hidden_L{L}'][:,KEEP] for L in range(13)}
def LNr(X): X=X-X.mean(1,keepdims=True); return X/X.std(1,keepdims=True)
def center_cv(X, y, nunits, gamma, lams, feat='exp', bias=-3.0, k=5, seed=0, rs=0):
    n=len(y); S={l:np.zeros((n,8)) for l in lams}
    for te in folds(n,k,seed,y):
        tr=np.setdiff1d(np.arange(n),te)
        mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; Z=(X-mu)/sd/np.sqrt(X.shape[1])
        rng=np.random.default_rng(rs)
        ci = rng.choice(tr,nunits,replace=False) if nunits<len(tr) else tr
        Cc=Z[ci]
        if feat=='rbf':
            sq=(Z**2).sum(1); Hf=np.exp(-gamma*np.maximum(sq[:,None]+(Cc**2).sum(1)[None]-2*Z@Cc.T,0))
        elif feat=='exp': Hf=np.exp(2*gamma*Z@Cc.T)
        elif feat=='tanh': Hf=np.tanh(gamma*Z@Cc.T+bias)+1
        Ht=Hf[tr]; T=np.eye(8)[y[tr]]-1/8
        G=Ht.T@Ht; sc=np.trace(G)/G.shape[0]
        for l in lams:
            Wt=np.linalg.solve(G+l*sc*np.eye(Ht.shape[1]),Ht.T@T); S[l][te]=(Hf@Wt)[te]
    return {l:round((S[l].argmax(1)==y).mean(),4) for l in lams}
lams=(1e-4,1e-3,1e-2,1e-1)
for L in [0,1,9]:
    X=LNr(M[L])
    print(L,'rbf 768',center_cv(X,y,768,0.4,lams,feat='rbf'))
    print(L,'rbf all',center_cv(X,y,5000,0.4,lams,feat='rbf'))
    print(L,'exp 768',center_cv(X,y,768,0.4,lams,feat='exp'))
    print(L,'tanh 768',center_cv(X,y,768,0.4,lams,feat='tanh'))
